const error = $json;
const errorDetails = {
  error_id: `ERR-${Date.now()}`,
  timestamp: new Date().toISOString(),
  workflow: { id: error.workflow?.id, name: error.workflow?.name },
  execution: { id: error.execution?.id, url: error.execution?.url },
  node: { name: error.node?.name, type: error.node?.type },
  error: { message: error.message || 'Unknown error', stack: error.stack }
};
// Classify error type
const msg = (error.message || '').toLowerCase();
let severity = 'medium';
let action = 'log_and_alert';
if (msg.includes('rate limit')) { severity = 'low'; action = 'queued_for_retry'; }
else if (msg.includes('timeout')) { severity = 'medium'; action = 'retry_once'; }
else if (msg.includes('authentication') || msg.includes('auth')) { severity = 'critical'; action = 'alert_immediately'; }
else if ((error.node?.type || '').includes('servicenow')) { severity = 'high'; action = 'queue_for_manual'; }
return {json: {...errorDetails, severity, action}};

const errorLog = {...$json, logged_at: new Date().toISOString()};
console.log('ERROR_LOG:', JSON.stringify(errorLog));
return {json: errorLog};
